#include <stdio.h>

int popcount(int x) {
    int c = 0;
    while (x) {
        c += x & 1;
        x >>= 1;
    }
    return c;
}

int main() {
    int L, C;
    scanf("%d %d", &L, &C);

    int P;
    scanf("%d", &P);

    int black[6][6] = {0};
    for (int i = 0; i < P; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        black[x - 1][y - 1] = 1;
    }

    int cand[6] = {0};

    for (int r = 0; r < L; r++) {
        for (int c = 0; c < C; c++) {
            if (black[r][c]) continue;

            int ok = 0;
            if (r > 0 && black[r - 1][c]) ok = 1;
            if (r + 1 < L && black[r + 1][c]) ok = 1;
            if (c > 0 && black[r][c - 1]) ok = 1;
            if (c + 1 < C && black[r][c + 1]) ok = 1;

            if (ok) cand[r] |= (1 << c);
        }
    }

    int S = 1 << C;
    int dp[64], ndp[64];

    for (int i = 0; i < S; i++) dp[i] = -1000000;
    dp[0] = 0;

    for (int r = 0; r < L; r++) {
        for (int i = 0; i < S; i++) ndp[i] = -1000000;

        for (int prev = 0; prev < S; prev++) {
            if (dp[prev] < 0) continue;

            for (int mask = 0; mask < S; mask++) {
                if (mask & ~cand[r]) continue;
                if (mask & (mask << 1)) continue;
                if (mask & prev) continue;

                int val = dp[prev] + popcount(mask);
                if (val > ndp[mask]) ndp[mask] = val;
            }
        }

        for (int i = 0; i < S; i++) dp[i] = ndp[i];
    }

    int ans = 0;
    for (int i = 0; i < S; i++) {
        if (dp[i] > ans) ans = dp[i];
    }

    printf("%d\n", ans);
    return 0;
}
